INSERT INTO pokemons (id, name, type, sprite_path, base_stats, description) VALUES
  (1, 'Bulbasaur', 'Grass/Poison', '/sprites/001-bulbasaur.png', '{"attack":49,"defense":49,"hp":45,"special":65,"speed":45}', 'A strange seed was planted on its back at birth. The plant sprouts and grows with this Pokemon.'),
  (2, 'Ivysaur', 'Grass/Poison', '/sprites/002-ivysaur.png', '{"attack":62,"defense":63,"hp":60,"special":80,"speed":60}', 'When the bulb on its back grows large, it appears to lose the ability to stand on its hind legs.'),
  (3, 'Venusaur', 'Grass/Poison', '/sprites/003-venusaur.png', '{"attack":82,"defense":83,"hp":80,"special":100,"speed":80}', 'The plant blooms when it is absorbing solar energy. It stays on the move to seek sunlight.'),
  (4, 'Charmander', 'Fire', '/sprites/004-charmander.png', '{"attack":52,"defense":43,"hp":39,"special":50,"speed":65}', 'Obviously prefers hot places. When it rains, steam is said to spout from the tip of its tail.'),
  (5, 'Charmeleon', 'Fire', '/sprites/005-charmeleon.png', '{"attack":64,"defense":58,"hp":58,"special":65,"speed":80}', 'When it swings its burning tail, it elevates the temperature to unbearably hot levels.'),
  (6, 'Charizard', 'Fire/Flying', '/sprites/006-charizard.png', '{"attack":84,"defense":78,"hp":78,"special":85,"speed":100}', 'Spits fire that is hot enough to melt boulders. Known to cause forest fires unintentionally.'),
  (7, 'Squirtle', 'Water', '/sprites/007-squirtle.png', '{"attack":48,"defense":65,"hp":44,"special":50,"speed":43}', 'After birth, its back swells and hardens into a shell. Powerfully sprays foam from its mouth.'),
  (8, 'Wartortle', 'Water', '/sprites/008-wartortle.png', '{"attack":63,"defense":80,"hp":59,"special":65,"speed":58}', 'Often hides in water to stalk unwary prey. For swimming fast, it moves its ears to maintain balance.'),
  (9, 'Blastoise', 'Water', '/sprites/009-blastoise.png', '{"attack":83,"defense":100,"hp":79,"special":85,"speed":78}', 'A brutal Pokemon with pressurized water jets on its shell. They are used for high speed tackles.'),
  (10, 'Caterpie', 'Bug', '/sprites/010-caterpie.png', '{"attack":30,"defense":35,"hp":45,"special":20,"speed":45}', 'Its short feet are tipped with suction pads that enable it to tirelessly climb slopes and walls.'),
  (11, 'Metapod', 'Bug', '/sprites/011-metapod.png', '{"attack":20,"defense":55,"hp":50,"special":25,"speed":30}', 'This Pokemon is vulnerable to attack while its shell is soft, exposing its weak and tender body.'),
  (12, 'Butterfree', 'Bug/Flying', '/sprites/012-butterfree.png', '{"attack":45,"defense":50,"hp":60,"special":90,"speed":70}', 'In battle, it flaps its wings at high speed to release highly toxic dust into the air.'),
  (13, 'Weedle', 'Bug/Poison', '/sprites/013-weedle.png', '{"attack":35,"defense":30,"hp":40,"special":20,"speed":50}', 'Often found in forests, eating leaves. It has a sharp venomous stinger on its head.'),
  (14, 'Kakuna', 'Bug/Poison', '/sprites/014-kakuna.png', '{"attack":25,"defense":50,"hp":45,"special":25,"speed":35}', 'Almost incapable of moving, this Pokemon can only harden its shell to protect itself from predators.'),
  (15, 'Beedrill', 'Bug/Poison', '/sprites/015-beedrill.png', '{"attack":90,"defense":40,"hp":65,"special":45,"speed":75}', 'Flies at high speed and attacks using its large venomous stingers on its forelegs and tail.'),
  (16, 'Pidgey', 'Normal/Flying', '/sprites/016-pidgey.png', '{"attack":45,"defense":40,"hp":40,"special":35,"speed":56}', 'A common sight in forests and woods. It flaps its wings at ground level to kick up blinding sand.'),
  (17, 'Pidgeotto', 'Normal/Flying', '/sprites/017-pidgeotto.png', '{"attack":60,"defense":55,"hp":63,"special":50,"speed":71}', 'Very protective of its sprawling territorial area, this Pokemon will fiercely peck at any intruder.'),
  (18, 'Pidgeot', 'Normal/Flying', '/sprites/018-pidgeot.png', '{"attack":80,"defense":75,"hp":83,"special":70,"speed":101}', 'When hunting, it skims the surface of water at high speed to pick off unwary prey such as Magikarp.'),
  (19, 'Rattata', 'Normal', '/sprites/019-rattata.png', '{"attack":56,"defense":35,"hp":30,"special":25,"speed":72}', 'Bites anything when it attacks. Small and very quick, it is a common sight in many places.'),
  (20, 'Raticate', 'Normal', '/sprites/020-raticate.png', '{"attack":81,"defense":60,"hp":55,"special":50,"speed":97}', 'It uses its whiskers to maintain its balance. It apparently slows down if they are cut off.'),
  (21, 'Spearow', 'Normal/Flying', '/sprites/021-spearow.png', '{"attack":60,"defense":30,"hp":40,"special":30,"speed":70}', 'Eats bugs in grassy areas. It has to flap its short wings at high speed to stay airborne.'),
  (22, 'Fearow', 'Normal/Flying', '/sprites/022-fearow.png', '{"attack":90,"defense":65,"hp":65,"special":61,"speed":100}', 'With its huge and magnificent wings, it can keep aloft without ever having to land for rest.'),
  (23, 'Ekans', 'Poison', '/sprites/023-ekans.png', '{"attack":60,"defense":44,"hp":35,"special":40,"speed":55}', 'Moves silently and stealthily. Eats the eggs of birds, such as Pidgey and Spearow, whole.'),
  (24, 'Arbok', 'Poison', '/sprites/024-arbok.png', '{"attack":95,"defense":69,"hp":60,"special":65,"speed":80}', 'It is rumored that the ferocious warning markings on its belly differ from area to area.'),
  (25, 'Pikachu', 'Electric', '/sprites/025-pikachu.png', '{"attack":55,"defense":40,"hp":35,"special":50,"speed":90}', 'When several of these Pokemon gather, their electricity could build and cause lightning storms.'),
  (26, 'Raichu', 'Electric', '/sprites/026-raichu.png', '{"attack":90,"defense":55,"hp":60,"special":90,"speed":110}', 'Its long tail serves as a ground to protect itself from its own high voltage power.'),
  (27, 'Sandshrew', 'Ground', '/sprites/027-sandshrew.png', '{"attack":75,"defense":85,"hp":50,"special":30,"speed":40}', 'Burrows deep underground in arid locations far from water. It only emerges to hunt prey.'),
  (28, 'Sandslash', 'Ground', '/sprites/028-sandslash.png', '{"attack":100,"defense":110,"hp":75,"special":55,"speed":65}', 'Curls up into a spiny ball when threatened. It can roll while curled up to attack or escape.'),
  (29, 'Nidoran♀', 'Poison', '/sprites/029-nidoran-f.png', '{"attack":47,"defense":52,"hp":55,"special":40,"speed":41}', 'Although small, its venomous barbs render this Pokemon dangerous. The female has smaller horns.'),
  (30, 'Nidorina', 'Poison', '/sprites/030-nidorina.png', '{"attack":62,"defense":67,"hp":70,"special":55,"speed":56}', 'The female Pokemon horn development is slower. It covers its body with a hard membrane.'),
  (31, 'Nidoqueen', 'Poison/Ground', '/sprites/031-nidoqueen.png', '{"attack":92,"defense":87,"hp":90,"special":75,"speed":76}', 'Its hard scales provide strong protection. It uses its hefty bulk to execute powerful moves.'),
  (32, 'Nidoran♂', 'Poison', '/sprites/032-nidoran-m.png', '{"attack":57,"defense":40,"hp":46,"special":40,"speed":50}', 'Stiffens its ears to sense danger. The larger its horns, the more powerful its secreted venom.'),
  (33, 'Nidorino', 'Poison', '/sprites/033-nidorino.png', '{"attack":72,"defense":57,"hp":61,"special":55,"speed":65}', 'An aggressive Pokemon that is quick to attack. The horn on its head secretes a powerful venom.'),
  (34, 'Nidoking', 'Poison/Ground', '/sprites/034-nidoking.png', '{"attack":102,"defense":77,"hp":81,"special":75,"speed":85}', 'It uses its powerful tail in battle to smash, constrict, then break the prey bones.'),
  (35, 'Clefairy', 'Fairy', '/sprites/035-clefairy.png', '{"attack":45,"defense":48,"hp":70,"special":60,"speed":35}', 'Its magical and cute appeal has many admirers. It is rare and found only in certain areas.'),
  (36, 'Clefable', 'Fairy', '/sprites/036-clefable.png', '{"attack":70,"defense":73,"hp":95,"special":85,"speed":60}', 'A timid Fairy Pokemon that is rarely seen. It will run and hide the moment it senses people.'),
  (37, 'Vulpix', 'Fire', '/sprites/037-vulpix.png', '{"attack":41,"defense":40,"hp":38,"special":65,"speed":65}', 'At the time of birth, it has just one tail. The tail splits from its tip as it grows older.'),
  (38, 'Ninetales', 'Fire', '/sprites/038-ninetales.png', '{"attack":76,"defense":75,"hp":73,"special":81,"speed":100}', 'Very smart and vengeful. Grabbing one of its many tails could result in a 1000-year curse.'),
  (39, 'Jigglypuff', 'Normal/Fairy', '/sprites/039-jigglypuff.png', '{"attack":45,"defense":20,"hp":115,"special":25,"speed":20}', 'When its huge eyes light up, it sings a mysteriously soothing melody that lulls its enemies to sleep.'),
  (40, 'Wigglytuff', 'Normal/Fairy', '/sprites/040-wigglytuff.png', '{"attack":70,"defense":45,"hp":140,"special":50,"speed":45}', 'The body is soft and rubbery. When angered, it will suck in air and inflate itself to an enormous size.'),
  (41, 'Zubat', 'Poison/Flying', '/sprites/041-zubat.png', '{"attack":45,"defense":35,"hp":40,"special":40,"speed":55}', 'Forms colonies in perpetually dark places. Uses ultrasonic waves to identify and approach targets.'),
  (42, 'Golbat', 'Poison/Flying', '/sprites/042-golbat.png', '{"attack":80,"defense":70,"hp":75,"special":75,"speed":90}', 'Once it strikes, it will not stop draining energy from the victim even if it gets too heavy to fly.'),
  (43, 'Oddish', 'Grass/Poison', '/sprites/043-oddish.png', '{"attack":50,"defense":55,"hp":45,"special":75,"speed":30}', 'During the day, it keeps its face buried in the ground. At night, it wanders around sowing its seeds.'),
  (44, 'Gloom', 'Grass/Poison', '/sprites/044-gloom.png', '{"attack":65,"defense":70,"hp":60,"special":85,"speed":40}', 'The fluid that oozes from its mouth isn''t drool. It is a nectar that is used to attract prey.'),
  (45, 'Vileplume', 'Grass/Poison', '/sprites/045-vileplume.png', '{"attack":80,"defense":85,"hp":75,"special":100,"speed":50}', 'The larger its petals, the more toxic pollen it contains. It has the largest petals in the world.'),
  (46, 'Paras', 'Bug/Grass', '/sprites/046-paras.png', '{"attack":70,"defense":55,"hp":35,"special":55,"speed":25}', 'Burrows to suck tree roots. The mushrooms on its back grow by drawing nutrients from the bug host.'),
  (47, 'Parasect', 'Bug/Grass', '/sprites/047-parasect.png', '{"attack":95,"defense":80,"hp":60,"special":80,"speed":30}', 'A host-parasite pair in which the parasite mushroom has taken over the host bug. Prefers damp places.'),
  (48, 'Venonat', 'Bug/Poison', '/sprites/048-venonat.png', '{"attack":55,"defense":50,"hp":60,"special":40,"speed":45}', 'Lives in the shadows of tall trees where it eats insects. It is attracted to light at night.'),
  (49, 'Venomoth', 'Bug/Poison', '/sprites/049-venomoth.png', '{"attack":65,"defense":60,"hp":70,"special":90,"speed":90}', 'The dust-like scales covering its wings are color coded to indicate the kinds of poison it has.'),
  (50, 'Diglett', 'Ground', '/sprites/050-diglett.png', '{"attack":55,"defense":25,"hp":10,"special":45,"speed":95}', 'Lives about one yard underground where it feeds on plant roots. It also appears above ground.'),
  (51, 'Dugtrio', 'Ground', '/sprites/051-dugtrio.png', '{"attack":100,"defense":50,"hp":35,"special":70,"speed":120}', 'A team of Diglett triplets. It triggers huge earthquakes by burrowing 60 miles underground.'),
  (52, 'Meowth', 'Normal', '/sprites/052-meowth.png', '{"attack":45,"defense":35,"hp":40,"special":40,"speed":90}', 'Adores circular objects. Wanders the streets on a nightly basis to look for dropped loose change.'),
  (53, 'Persian', 'Normal', '/sprites/053-persian.png', '{"attack":70,"defense":65,"hp":65,"special":65,"speed":115}', 'Although its fur has many admirers, it is tough to raise as a pet because of its fickle meanness.'),
  (54, 'Psyduck', 'Water', '/sprites/054-psyduck.png', '{"attack":52,"defense":48,"hp":50,"special":65,"speed":55}', 'While lulling its enemies with its vacant look, this wily Pokemon will use psychokinetic powers.'),
  (55, 'Golduck', 'Water', '/sprites/055-golduck.png', '{"attack":82,"defense":78,"hp":80,"special":80,"speed":85}', 'Often seen swimming elegantly by lake shores. It is often mistaken for the Japanese monster, Kappa.'),
  (56, 'Mankey', 'Fighting', '/sprites/056-mankey.png', '{"attack":80,"defense":35,"hp":40,"special":35,"speed":70}', 'Extremely quick to anger. It could be docile one moment then thrashing away the next instant.'),
  (57, 'Primeape', 'Fighting', '/sprites/057-primeape.png', '{"attack":105,"defense":60,"hp":65,"special":60,"speed":95}', 'When angered, it loses all sense of itself and cannot even recognize its own trainer.'),
  (58, 'Growlithe', 'Fire', '/sprites/058-growlithe.png', '{"attack":70,"defense":45,"hp":55,"special":50,"speed":60}', 'A Pokemon that has been admired for its courage. It will fearlessly bark at any larger opponent.'),
  (59, 'Arcanine', 'Fire', '/sprites/059-arcanine.png', '{"attack":110,"defense":80,"hp":90,"special":80,"speed":95}', 'A Pokemon that has been admired for its speed. It appears to run about as fast as a four-legged animal.'),
  (60, 'Poliwag', 'Water', '/sprites/060-poliwag.png', '{"attack":50,"defense":40,"hp":40,"special":40,"speed":90}', 'Capable of swimming upstream. The swirl pattern on its belly has been shown to have some correlation to the rotation of the planets.'),
  (61, 'Poliwhirl', 'Water', '/sprites/061-poliwhirl.png', '{"attack":65,"defense":65,"hp":65,"special":50,"speed":90}', 'Capable of living in or out of water. When out of water, it sweats to keep its body slimy.'),
  (62, 'Poliwrath', 'Water/Fighting', '/sprites/062-poliwrath.png', '{"attack":85,"defense":95,"hp":90,"special":70,"speed":70}', 'An adept swimmer at both the front crawl and butterfly stroke. Easily overtakes the best human swimmers.'),
  (63, 'Abra', 'Psychic', '/sprites/063-abra.png', '{"attack":20,"defense":15,"hp":25,"special":105,"speed":90}', 'Using its ability to read minds, it will identify impending danger and TELEPORT to safety.'),
  (64, 'Kadabra', 'Psychic', '/sprites/064-kadabra.png', '{"attack":35,"defense":30,"hp":40,"special":120,"speed":105}', 'It emits special alpha waves from its body that induce headaches just by being close by.'),
  (65, 'Alakazam', 'Psychic', '/sprites/065-alakazam.png', '{"attack":50,"defense":45,"hp":55,"special":135,"speed":120}', 'Its brain can outperform a supercomputer. Its IQ (intelligence quotient) is said to be 5,000.'),
  (66, 'Machop', 'Fighting', '/sprites/066-machop.png', '{"attack":80,"defense":50,"hp":70,"special":35,"speed":35}', 'Loves to build its muscles. It trains in all manufacturing and construction industries by night.'),
  (67, 'Machoke', 'Fighting', '/sprites/067-machoke.png', '{"attack":100,"defense":70,"hp":80,"special":50,"speed":45}', 'Its muscular body is so powerful, it must wear a power save belt to be able to regulate its movements.'),
  (68, 'Machamp', 'Fighting', '/sprites/068-machamp.png', '{"attack":130,"defense":80,"hp":90,"special":65,"speed":55}', 'Using its heavy muscles, it throws powerful punches that can send the victim clear over the horizon.'),
  (69, 'Bellsprout', 'Grass/Poison', '/sprites/069-bellsprout.png', '{"attack":75,"defense":35,"hp":50,"special":70,"speed":40}', 'A carnivorous Pokemon that traps and eats bugs. It uses its root feet to soak up needed moisture.'),
  (70, 'Weepinbell', 'Grass/Poison', '/sprites/070-weepinbell.png', '{"attack":90,"defense":50,"hp":65,"special":85,"speed":55}', 'It spits out POISONPOWDER to immobilize the enemy and then finishes it with a spray of ACID.'),
  (71, 'Victreebel', 'Grass/Poison', '/sprites/071-victreebel.png', '{"attack":105,"defense":65,"hp":80,"special":95,"speed":70}', 'Said to live in huge colonies deep in jungles, although no one has ever returned from there.'),
  (72, 'Tentacool', 'Water/Poison', '/sprites/072-tentacool.png', '{"attack":40,"defense":35,"hp":40,"special":100,"speed":70}', 'Drifts in shallow seas. Anglers who hook them from shore are said to get sick from the ACID they spray.'),
  (73, 'Tentacruel', 'Water/Poison', '/sprites/073-tentacruel.png', '{"attack":70,"defense":65,"hp":80,"special":120,"speed":120}', 'The tentacles are normally kept short. On hunts, the ensnare and immobilize prey.'),
  (74, 'Geodude', 'Rock/Ground', '/sprites/074-geodude.png', '{"attack":80,"defense":100,"hp":40,"special":30,"speed":20}', 'Found. Mistaking them for rocks, people often step or trip on them.'),
  (75, 'Graveler', 'Rock/Ground', '/sprites/075-graveler.png', '{"attack":95,"defense":115,"hp":55,"special":45,"speed":35}', 'Rolls down slopes to move. It rolls over any obstacle without slowing or changing its direction.'),
  (76, 'Golem', 'Rock/Ground', '/sprites/076-golem.png', '{"attack":120,"defense":130,"hp":80,"special":55,"speed":45}', 'After shedding its shell, its soft body turns hard. It appears to be waiting for something.'),
  (77, 'Ponyta', 'Fire', '/sprites/077-ponyta.png', '{"attack":85,"defense":55,"hp":50,"special":65,"speed":90}', 'Its hooves are 10 times harder than diamonds. It can trample anything completely flat in little time.'),
  (78, 'Rapidash', 'Fire', '/sprites/078-rapidash.png', '{"attack":100,"defense":70,"hp":65,"special":80,"speed":105}', 'Very rarely seen, when spotted it is seen as a magnificent steed galloping across plains.'),
  (79, 'Slowpoke', 'Water/Psychic', '/sprites/079-slowpoke.png', '{"attack":65,"defense":65,"hp":90,"special":40,"speed":15}', 'Incredibly slow and dopey. It takes 5 seconds for it to feel pain when under attack.'),
  (80, 'Slowbro', 'Water/Psychic', '/sprites/080-slowbro.png', '{"attack":75,"defense":80,"hp":95,"special":100,"speed":30}', 'The SHELLDER that is latched onto SLOWPOKE''s tail is not using its shell for protection.'),
  (81, 'Magnemite', 'Electric/Steel', '/sprites/081-magnemite.png', '{"attack":35,"defense":70,"hp":25,"special":95,"speed":45}', 'It is a living magnet. It uses its magnetic body to float in the air and shoots electricity at foes.'),
  (82, 'Magneton', 'Electric/Steel', '/sprites/082-magneton.png', '{"attack":60,"defense":95,"hp":50,"special":120,"speed":70}', 'When many MAGNETON gather together, the magnetic field becomes stronger than usual.'),
  (83, 'Farfetch''d', 'Normal/Flying', '/sprites/083-farfetchd.png', '{"attack":90,"defense":55,"hp":52,"special":58,"speed":60}', 'The sprig of green onions it holds is its weapon. It is used much like a metal sword.'),
  (84, 'Doduo', 'Normal/Flying', '/sprites/084-doduo.png', '{"attack":85,"defense":45,"hp":35,"special":35,"speed":75}', 'A bird that wyverns with two heads. However, they never pick up the same prey at the same time.'),
  (85, 'Dodrio', 'Normal/Flying', '/sprites/085-dodrio.png', '{"attack":110,"defense":70,"hp":60,"special":60,"speed":110}', 'An unnerved bird that uses its three heads to argue. It can fly for short distances at high speed.'),
  (86, 'Seel', 'Water', '/sprites/086-seel.png', '{"attack":45,"defense":55,"hp":65,"special":65,"speed":45}', 'The protruding horn on its head is very hard. It is used for bashing through thick ice.'),
  (87, 'Dewgong', 'Water/Ice', '/sprites/087-dewgong.png', '{"attack":70,"defense":80,"hp":90,"special":95,"speed":70}', 'Stores thermal energy in its body. When the temperature drops in winter, its tail is said to become harder than diamond.'),
  (88, 'Grimer', 'Poison', '/sprites/088-grimer.png', '{"attack":80,"defense":50,"hp":80,"special":40,"speed":25}', 'Appears in filthy areas. Thrives by feeding on industrial waste, sludge, and garbage.'),
  (89, 'Muk', 'Poison', '/sprites/089-muk.png', '{"attack":105,"defense":75,"hp":105,"special":65,"speed":50}', 'Thickly covered with filthy garbage. Toxic waste seeps from its body and keeps it fresh and clean.'),
  (90, 'Shellder', 'Water', '/sprites/090-shellder.png', '{"attack":65,"defense":100,"hp":30,"special":45,"speed":40}', 'When attacked, it launches its horns in quick volleys. Its innards have never been seen.'),
  (91, 'Cloyster', 'Water/Ice', '/sprites/091-cloyster.png', '{"attack":95,"defense":180,"hp":50,"special":85,"speed":70}', 'When attacked, it launches its horns in quick volleys. Its innards have never been seen.'),
  (92, 'Gastly', 'Ghost/Poison', '/sprites/092-gastly.png', '{"attack":35,"defense":30,"hp":30,"special":100,"speed":80}', 'Almost invisible, this gaseous Pokemon cloaks the target and puts it to sleep without notice.'),
  (93, 'Haunter', 'Ghost/Poison', '/sprites/093-haunter.png', '{"attack":50,"defense":45,"hp":45,"special":115,"speed":95}', 'Because of its ability to slip through block walls, it is said to be from another dimension.'),
  (94, 'Gengar', 'Ghost/Poison', '/sprites/094-gengar.png', '{"attack":65,"defense":60,"hp":60,"special":130,"speed":110}', 'Under a full moon, this Pokemon likes to mimic the shadows of people and laugh at their fright.'),
  (95, 'Onix', 'Rock/Ground', '/sprites/095-onix.png', '{"attack":45,"defense":160,"hp":35,"special":30,"speed":70}', 'As it grows, the stone portions of its body harden to become similar to a diamond, but it is still brittle.'),
  (96, 'Drowzee', 'Psychic', '/sprites/096-drowzee.png', '{"attack":48,"defense":45,"hp":60,"special":43,"speed":42}', 'Puts enemies to sleep then eats their dreams. Occasionally gets sick from eating bad dreams.'),
  (97, 'Hypno', 'Psychic', '/sprites/097-hypno.png', '{"attack":73,"defense":70,"hp":85,"special":73,"speed":67}', 'When it locks eyes with an enemy, it will use a constellation of different PSI moves.'),
  (98, 'Krabby', 'Water', '/sprites/098-krabby.png', '{"attack":105,"defense":90,"hp":30,"special":25,"speed":50}', 'Its pincers are not only powerful for crushing, but are also used to hold its prey and not let go.'),
  (99, 'Kingler', 'Water', '/sprites/099-kingler.png', '{"attack":130,"defense":115,"hp":55,"special":50,"speed":75}', 'The large pincer has 10000 hp of crushing force. However, its huge size makes it unwieldy to use.'),
  (100, 'Voltorb', 'Electric', '/sprites/100-voltorb.png', '{"attack":30,"defense":50,"hp":40,"special":55,"speed":100}', 'Usually found in power plants. Easily mistaken for a POKEBALL, they have zapped many people.'),
  (101, 'Electrode', 'Electric', '/sprites/101-electrode.png', '{"attack":50,"defense":70,"hp":60,"special":80,"speed":150}', 'It stores electric energy under very high pressure. It often explodes with the slightest provocation.'),
  (102, 'Exeggcute', 'Grass/Psychic', '/sprites/102-exeggcute.png', '{"attack":40,"defense":80,"hp":60,"special":60,"speed":40}', 'Often mistaken for eggs. When disturbed, it quickly separates and escapes in panic.'),
  (103, 'Exeggutor', 'Grass/Psychic', '/sprites/103-exeggutor.png', '{"attack":95,"defense":85,"hp":95,"special":125,"speed":55}', 'Legend has it that on rare occasions, one of its heads will drop off and continue living as an EXEGGCUTE.'),
  (104, 'Cubone', 'Ground', '/sprites/104-cubone.png', '{"attack":50,"defense":95,"hp":50,"special":40,"speed":35}', 'Because it never removes its skull helmet, no one has ever seen this Pokemon''s real face.'),
  (105, 'Marowak', 'Ground', '/sprites/105-marowak.png', '{"attack":80,"defense":110,"hp":60,"special":50,"speed":45}', 'The bone it holds is its key weapon. It throws the bone skillfully like a boomerang to KO targets.'),
  (106, 'Hitmonlee', 'Fighting', '/sprites/106-hitmonlee.png', '{"attack":120,"defense":53,"hp":50,"special":35,"speed":87}', 'When in a hurry, its legs lengthen progressively. It runs smoothly as if gliding on the ground.'),
  (107, 'Hitmonchan', 'Fighting', '/sprites/107-hitmonchan.png', '{"attack":105,"defense":79,"hp":50,"special":35,"speed":76}', 'While apparently doing nothing, it is unloading punches. When it unloads, it uses all three fists.'),
  (108, 'Lickitung', 'Normal', '/sprites/108-lickitung.png', '{"attack":55,"defense":75,"hp":90,"special":60,"speed":30}', 'Its tongue can be extended like a chameleon''s. It leaves a tingling sensation when it licks enemies.'),
  (109, 'Koffing', 'Poison', '/sprites/109-koffing.png', '{"attack":65,"defense":95,"hp":40,"special":60,"speed":35}', 'Because it stores several kinds of toxic gases in its body, it is prone to exploding without warning.'),
  (110, 'Weezing', 'Poison', '/sprites/110-weezing.png', '{"attack":90,"defense":120,"hp":65,"special":85,"speed":60}', 'Where two kinds of poison gases meet, 2 heads appear and form a WEEDING - a Pokemon that has the power of poison gas.'),
  (111, 'Rhyhorn', 'Ground/Rock', '/sprites/111-rhyhorn.png', '{"attack":85,"defense":95,"hp":80,"special":30,"speed":25}', 'A Pokemon with a huge body. Its horn is very sharp. The horn is said to be harder than diamond.'),
  (112, 'Rhydon', 'Ground/Rock', '/sprites/112-rhydon.png', '{"attack":130,"defense":120,"hp":105,"special":45,"speed":40}', 'Protected by an armor-like hide, it is capable of living in molten lava of 3,600 degrees.'),
  (113, 'Chansey', 'Normal', '/sprites/113-chansey.png', '{"attack":5,"defense":5,"hp":250,"special":105,"speed":50}', 'A kindly Pokemon that lays highly nutritious eggs and shares them with injured Pokemon or people.'),
  (114, 'Tangela', 'Grass', '/sprites/114-tangela.png', '{"attack":55,"defense":115,"hp":65,"special":100,"speed":60}', 'The blue vines that cover its body cannot be seen. They grow differently each day.'),
  (115, 'Kangaskhan', 'Normal', '/sprites/115-kangaskhan.png', '{"attack":95,"defense":80,"hp":105,"special":40,"speed":90}', 'The infant rarely ventures out of its mother''s pouch. It sucks milk from its mother and never quits.'),
  (116, 'Horsea', 'Water', '/sprites/116-horsea.png', '{"attack":40,"defense":70,"hp":30,"special":70,"speed":60}', 'Known to shoot down prey using its fins. It has excellent accuracy. It attacks using its big tail.'),
  (117, 'Seadra', 'Water', '/sprites/117-seadra.png', '{"attack":65,"defense":95,"hp":55,"special":95,"speed":85}', 'Capable of swimming backwards by flapping its large fins. The fin spears are toxic and cause numbness.'),
  (118, 'Goldeen', 'Water', '/sprites/118-goldeen.png', '{"attack":67,"defense":60,"hp":45,"special":50,"speed":63}', 'Its horn spins like a drill. The horn serves as a weapon for digging holes in river bottoms.'),
  (119, 'Seaking', 'Water', '/sprites/119-seaking.png', '{"attack":92,"defense":65,"hp":80,"special":65,"speed":68}', 'In the autumn spawning season, they can be seen swimming powerfully up rivers and creeks.'),
  (120, 'Staryu', 'Water', '/sprites/120-staryu.png', '{"attack":45,"defense":55,"hp":30,"special":70,"speed":85}', 'An enigmatic Pokemon that can effortlessly regenerate any appendage it loses in battle.'),
  (121, 'Starmie', 'Water/Psychic', '/sprites/121-starmie.png', '{"attack":75,"defense":85,"hp":60,"special":100,"speed":115}', 'Its central core glows with the seven colors of the rainbow. Some people value the core as a gem.'),
  (122, 'Mr. Mime', 'Psychic/Fairy', '/sprites/122-mr-mime.png', '{"attack":45,"defense":65,"hp":40,"special":100,"speed":90}', 'If interrupted while it is miming, it will slap around the offender with its broad hands.'),
  (123, 'Scyther', 'Bug/Flying', '/sprites/123-scyther.png', '{"attack":110,"defense":80,"hp":70,"special":55,"speed":105}', 'With ninja-like agility and speed, it creates the illusion that there is more than one.'),
  (124, 'Jynx', 'Ice/Psychic', '/sprites/124-jynx.png', '{"attack":50,"defense":35,"hp":65,"special":95,"speed":95}', 'It seductively wiggles its hips as it walks. It can cause people to dance in unison with it.'),
  (125, 'Electabuzz', 'Electric', '/sprites/125-electabuzz.png', '{"attack":83,"defense":57,"hp":65,"special":85,"speed":105}', 'Normally found near power plants, they wander about in search of electricity.'),
  (126, 'Magmar', 'Fire', '/sprites/126-magmar.png', '{"attack":95,"defense":57,"hp":65,"special":85,"speed":93}', 'Its body always burns like an ember. It causes flames to erupt on contact with anything.'),
  (127, 'Pinsir', 'Bug', '/sprites/127-pinsir.png', '{"attack":125,"defense":100,"hp":65,"special":55,"speed":85}', 'If it fails to crush the victim in its pincers, it will swing it around and toss it hard.'),
  (128, 'Tauros', 'Normal', '/sprites/128-tauros.png', '{"attack":100,"defense":95,"hp":75,"special":70,"speed":110}', 'When it targets an enemy, it charges furiously at full speed. It is protected by its horns.'),
  (129, 'Magikarp', 'Water', '/sprites/129-magikarp.png', '{"attack":10,"defense":55,"hp":20,"special":15,"speed":80}', 'In the distant past, it was somewhat stronger than the horribly weak descendants that exist today.'),
  (130, 'Gyarados', 'Water/Flying', '/sprites/130-gyarados.png', '{"attack":125,"defense":79,"hp":95,"special":100,"speed":81}', 'Rarely seen in the wild. Huge and vicious, it attacks any moving object it sees.'),
  (131, 'Lapras', 'Water/Ice', '/sprites/131-lapras.png', '{"attack":85,"defense":80,"hp":130,"special":95,"speed":60}', 'A Pokemon that has been overhunted almost to extinction. It can ferry people across bodies of water.'),
  (132, 'Ditto', 'Normal', '/sprites/132-ditto.png', '{"attack":48,"defense":48,"hp":48,"special":48,"speed":48}', 'Capable of copying an enemy''s genetic code to become an identical copy, but the copied data becomes garbled.'),
  (133, 'Eevee', 'Normal', '/sprites/133-eevee.png', '{"attack":55,"defense":50,"hp":55,"special":65,"speed":55}', 'Its genetic code is irregular. It may mutate if it is exposed to radiation from element STONE.'),
  (134, 'Vaporeon', 'Water', '/sprites/134-vaporeon.png', '{"attack":65,"defense":60,"hp":130,"special":110,"speed":65}', 'Lives close to water. Its long tail is ridged with a fin which is often mistaken for a mermaid''s.'),
  (135, 'Jolteon', 'Electric', '/sprites/135-jolteon.png', '{"attack":65,"defense":60,"hp":65,"special":110,"speed":130}', 'It accumulates negative ions in the atmosphere to blast out 10000-volt lightning bolts.'),
  (136, 'Flareon', 'Fire', '/sprites/136-flareon.png', '{"attack":130,"defense":60,"hp":65,"special":110,"speed":65}', 'When storing thermal energy in its body, its temperature could soar to over 1600 degrees.'),
  (137, 'Porygon', 'Normal', '/sprites/137-porygon.png', '{"attack":60,"defense":70,"hp":65,"special":75,"speed":40}', 'A Pokemon that consists of programming code. Capable of moving freely in cyberspace.'),
  (138, 'Omanyte', 'Rock/Water', '/sprites/138-omanyte.png', '{"attack":40,"defense":100,"hp":35,"special":90,"speed":35}', 'Although long extinct, in rare cases, it can be genetically resurrected from fossils.'),
  (139, 'Omastar', 'Rock/Water', '/sprites/139-omastar.png', '{"attack":60,"defense":125,"hp":70,"special":115,"speed":55}', 'A prehistoric Pokemon that died out when its heavy shell made it impossible to catch prey.'),
  (140, 'Kabuto', 'Rock/Water', '/sprites/140-kabuto.png', '{"attack":80,"defense":90,"hp":30,"special":45,"speed":55}', 'A Pokemon that was resurrected from a fossil. It has a hard shell that protects its tiny body.'),
  (141, 'Kabutops', 'Rock/Water', '/sprites/141-kabutops.png', '{"attack":115,"defense":105,"hp":60,"special":70,"speed":80}', 'Its sleek shape is perfect for swimming. It can slice prey with its sharp claws.'),
  (142, 'Aerodactyl', 'Rock/Flying', '/sprites/142-aerodactyl.png', '{"attack":105,"defense":65,"hp":80,"special":60,"speed":130}', 'A ferocious, prehistoric Pokemon that goes for the enemy''s throat with its serrated saw-like fangs.'),
  (143, 'Snorlax', 'Normal', '/sprites/143-snorlax.png', '{"attack":110,"defense":65,"hp":160,"special":65,"speed":30}', 'Very lazy. Just eats and sleeps. As its rotund bulk builds, it becomes steadily more slothful.'),
  (144, 'Articuno', 'Ice/Flying', '/sprites/144-articuno.png', '{"attack":85,"defense":100,"hp":90,"special":125,"speed":85}', 'A legendary bird Pokemon that controls ice. The flapping of its wings chills the air.'),
  (145, 'Zapdos', 'Electric/Flying', '/sprites/145-zapdos.png', '{"attack":90,"defense":85,"hp":90,"special":125,"speed":100}', 'A legendary bird Pokemon that is said to appear from clouds while dropping enormous lightning bolts.'),
  (146, 'Moltres', 'Fire/Flying', '/sprites/146-moltres.png', '{"attack":100,"defense":90,"hp":90,"special":125,"speed":90}', 'Known as the legendary bird of fire. Each flap of its wings creates a dazzling flash of flames.'),
  (147, 'Dratini', 'Dragon', '/sprites/147-dratini.png', '{"attack":64,"defense":45,"hp":41,"special":50,"speed":50}', 'A rare Pokemon that is rarely seen. It has been hiding in a cave for some unknown time period.'),
  (148, 'Dragonair', 'Dragon', '/sprites/148-dragonair.png', '{"attack":84,"defense":65,"hp":61,"special":70,"speed":70}', 'A mystical Pokemon that exudes a gentle aura. It has the ability to change climate conditions.'),
  (149, 'Dragonite', 'Dragon/Flying', '/sprites/149-dragonite.png', '{"attack":134,"defense":95,"hp":91,"special":100,"speed":80}', 'An extremely rarely seen marine Pokemon. It is said to be capable of flying around the globe in about 16 hours.'),
  (150, 'Mewtwo', 'Psychic', '/sprites/150-mewtwo.png', '{"attack":110,"defense":90,"hp":106,"special":154,"speed":130}', 'It was created by a scientist after years of horrific gene splicing and DNA engineering experiments.'),
  (151, 'Mew', 'Psychic', '/sprites/151-mew.png', '{"attack":100,"defense":100,"hp":100,"special":100,"speed":100}', 'So rare that it is still said to be a mirage by many experts. It has the power to learn any move.');
